 }

 var idenlocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location')
 idenlocationGr.addQuery('identity',vaInputs.user_sys_id);
 idenlocationGr.query();
 var location = "";
 if(idenlocationGr.next()){
 location = idenlocationGr.location;
 vaVars.user_location = location;
 gs.info("Location : "+location);
 }

 //get location Mobile Cred Config
 var dtInputs = {};
 dtInputs.user_location = vaVars.user_location;
 var result = new GuardianAIAgentHelper().getDTConfigs("a57ddb4833083650bf1221382e5c7b7e",dtInputs);
 gs.info("DT Result Mob Cred : "+JSON.stringify(result));
 vaVars.location_mobile_cred_enabled = result.MC_SUPPORT;
})()
