 // vaVars.ask_valid_to = "true";
 // }
 // vaVars.default_status = result.DEFAULT_STATUS;

 //default system
 var locationAdminGr = new GlideRecordSecure('x_aleen_snguardian_badge_office');
 locationAdminGr.addQuery('locationsLIKE'+vaVars.user_location);
 locationAdminGr.orderBy('order');
 locationAdminGr.query();
 if(locationAdminGr.next()){
 vaVars.default_system = locationAdminGr.system;
 }

 //default access
 if(location){
 var accessList = [];
 var accessLocationGr = new GlideRecordSecure('x_aleen_snguardian_access_location');
 accessLocationGr.addQuery('location', vaVars.user_location);
 accessLocationGr.addQuery('is_default', true);
 accessLocationGr.query();
 while (accessLocationGr.next()) {
 var accessLevel = accessLocationGr.access_level.toString(); // Convert to string
 if (accessList.indexOf(accessLevel) === -1) {
 accessList.push(accessLevel);
 }
 }
 vaVars.default_access = accessList.join(); 
 }
})()
